#nullable enable

namespace Allocation.Slices.Allocation;

/// <summary>
/// The actual work the reservation was taken FOR — charging a card, calling a partner, printing a ticket.
///
/// IT IS AN INTERFACE BECAUSE THE MODEL CANNOT SAY WHAT IT DOES, and that gap is the sharpest thing this
/// slice found. <c>gwt-issue-1</c> and <c>gwt-issue-3</c> have the SAME given= and the SAME when= and
/// different then= — one issues a grant, the other records a refusal — because whether the work succeeds
/// is not a fact about the system at all. The model's `$RefusedGrant` example data is the only thing that
/// distinguishes them, and that is exactly what CLAUDE.md says an example is for: it specifies the how
/// well enough to VERIFY and never well enough to GENERATE.
///
/// AND IT IS WHY THE COMPENSATING PATH EXISTS. If this were a database write, reserve and execute could
/// share a transaction and neither the reservation nor the release would be needed. A rollback cannot
/// un-call a partner, so the failure has to be recorded as a fact and undone by another command — which
/// is the Reservation Pattern's entire reason to be two steps.
/// </summary>
public interface IGrantExecutor
{
    Task<GrantVerdict> Execute(Guid grantId, Guid poolId, int slotNumber, CancellationToken cancellation);
}

/// <summary>What the work answered. A refusal is an ANSWER — it is not an exception and not a rejection.</summary>
public sealed record GrantVerdict(bool Accepted, string Reason = "")
{
    public static readonly GrantVerdict Yes = new(true);
    public static GrantVerdict No(string reason) => new(false, reason);
}

/// <summary>
/// A STAND-IN, and it is here for one reason: the compensating path has to be reachable end to end, and a
/// reference implementation has no partner to call.
///
/// It refuses exactly one well-known id and accepts everything else. That is a worse smell than
/// configuration would be — production code that knows a magic value — and it is the lesser evil, because
/// the alternative is a compensating path that no test can reach and that therefore is not really built.
/// It is registered in IssueGrantWakeup.RegisterServices, so a real system replaces one line.
/// </summary>
public sealed class StandInGrantExecutor : IGrantExecutor
{
    /// <summary>
    /// The one grant this stand-in always refuses. SeedData.RefusedGrant points at this constant rather
    /// than repeating the value, so the model's `$RefusedGrant` and the code agree by construction.
    /// </summary>
    public static readonly Guid AlwaysRefused = Guid.Parse("99999999-9999-9999-9999-999999999999");

    public const string RefusalReason = "TheWorkRefused";

    public Task<GrantVerdict> Execute(Guid grantId, Guid poolId, int slotNumber, CancellationToken cancellation)
        => Task.FromResult(grantId == AlwaysRefused ? GrantVerdict.No(RefusalReason) : GrantVerdict.Yes);
}
